INSERT INTO recipes (id, title, ingredients, instructions, total_time, yield, archived, created_at, updated_at) VALUES ('kgnk24xa', 'Rizses hús 2', '[{"label":"","items":["5 dkg füstölt szalonna","1 nagyobb fej vöröshagyma","4 gerezd fokhagyma","1 kg sertéslapocka vagy -comb (felkockázva)","2 ek sűrített paradicsom","Só, bors, vegeta ízlés szerint","2 tk őrölt kömény","1 ek pirospaprika","300 g rizs"]}]', '["A szalonnát felkockázom, és egy nagyobb lábasban elkezdem pirítani.","A hagymát apróra vágom, majd amikor a szalonna kiengedte a zsírját, hozzáadom.","Amikor a hagyma üvegesre dinsztelődött, hozzáadom a felkockázott húst, és magas lángon pirítani kezdem.","Kis idő múlva belekeverem a sűrített paradicsomot.","Rövid pirítás után hozzáadom a zúzott fokhagymát, sózom, borsozom, vegetával ízesítem, majd hozzáadom a köményt és a pirospaprikát is.","Néhány perc múlva belekeverem a rizst, és felöntöm annyi vízzel, ami a rizs súlyának nagyjából a kétszerese.","Amint felforrt, lefedem, és kis lángon, keverés nélkül főzöm 20–22 percig."]', '0:45', '5 adag', 0, '1970-01-01T00:00:00.000Z', '2025-08-29T22:37:00.000Z');
