INSERT INTO recipes (id, title, ingredients, instructions, total_time, yield, archived, created_at, updated_at) VALUES ('pdos32ns', 'Palacsinta 3', '[{"label":"","items":["20 dkg liszt","2 tojás","3 dl tej","3 dl szóda","1 csipet só"]}]', '["Felütjük a tojásokat, kicsit felverjük, majd hozzáadjuk a lisztet.","Apránként hígítjuk a tejjel és a vízzel, csipet sóval ízesítjük.","Forró serpenyőbe öntünk annyi tésztát, hogy ne legyen túl vastag a palacsinta, majd mindkét oldalát pirosra sütjük."]', '0:30', '20 darab', 1, '1970-01-01T00:00:00.000Z', '2025-08-29T22:38:00.000Z');
